units.exampleCode:
int indent = 0;
int fib(int n) {
    cerr << string(indent * 2, ' ') << "fib(" << n << ") enter" << endl;
    indent++;
    int result;
    if (n <= 1) result = n;
    else result = fib(n-1) + fib(n-2);
    indent--;
    cerr << string(indent * 2, ' ') << "fib(" << n << ") = " << result << endl;
    return result;
}

practice.expectedIdea:
int fact(int n) {
    cerr << "fact(" << n << ") enter" << endl;
    if (n <= 1) { cerr << "fact(" << n << ") = 1" << endl; return 1; }
    int r = n * fact(n - 1);
    cerr << "fact(" << n << ") = " << r << endl;
    return r;
}

